public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if(n <= 0 || start == null || end == null || start.length != end.length || paths == null) {
        return "cannot be travelled";
    }
    int dim = start.length;
    // helper to convert coordinates to key
    java.util.function.BiFunction<int[], Integer, String> keyFunc = (coords, d) -> {
        StringBuilder sb = new StringBuilder();
        for(int i=0;i<d;i++){
            sb.append(coords[i]);
            if(i<d-1) sb.append(",");
        }
        return sb.toString();
    };
    String startKey = keyFunc.apply(start, dim);
    String endKey = keyFunc.apply(end, dim);

    // Validate coordinates bounds
    java.util.function.IntConsumer validate = coord -> {
        if(coord < 0 || coord >= n) {
            throw new IllegalArgumentException();
        }
    };
    try {
        for(int v:start) validate.accept(v);
        for(int v:end) validate.accept(v);
    } catch(IllegalArgumentException e) {
        return "cannot be travelled";
    }

    java.util.Map<String, java.util.Set<String>> graph = new java.util.HashMap<>();
    for(int[] p: paths){
        if(p == null || p.length != 2*dim) continue;
        int[] p1 = new int[dim];
        int[] p2 = new int[dim];
        System.arraycopy(p,0,p1,0,dim);
        System.arraycopy(p,dim,p2,0,dim);
        String k1 = keyFunc.apply(p1, dim);
        String k2 = keyFunc.apply(p2, dim);
        graph.computeIfAbsent(k1, k->new java.util.HashSet<>()).add(k2);
        graph.computeIfAbsent(k2, k->new java.util.HashSet<>()).add(k1);
    }

    if(startKey.equals(endKey)){
        return "can be travelled";
    }

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while(!queue.isEmpty()){
        String cur = queue.poll();
        java.util.Set<String> neighbours = graph.get(cur);
        if(neighbours == null) continue;
        for(String neigh: neighbours){
            if(visited.contains(neigh)) continue;
            if(neigh.equals(endKey)) return "can be travelled";
            visited.add(neigh);
            queue.add(neigh);
        }
    }
    return "cannot be travelled";
}

