        int a = numerator;
        int b = denominator;
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        int gcd = a;
        numerator /= gcd;
        denominator /= gcd;
        result = numerator + "/" + denominator;
    }
