            count += dfs(i, mask | (1 << i), n, fullMask, arr, memo);
        }
        memo.put(key, count);
        return count;
    }
    private static boolean isSquare(int sum) {
        int r = (int)Math.sqrt(sum);
        return r * r == sum;
    }
